using System.Diagnostics;
using System.Text.Json;
using PuddingSsh.Contracts;
using PuddingSsh.Execution;
using PuddingSshTests;

static void Emit(object x) => Console.WriteLine(JsonSerializer.Serialize(x));
static SshCoordinatorOptions Opt(int q = 8) => new() { CleanupGrace = TimeSpan.FromMilliseconds(50), MaxQuarantinedResources = q };
static SshOperationCoordinator Coordinator(ISshTransportSession s) => new(new FakeTransportFactory { OnConnect = (_, _) => Task.FromResult(s) }, new FakeIdentityProvider(), Opt());

// Sync execute entry returns only after a deliberately finite block.
{
    var session = new FakeSession { SynchronousBlockBeforeExecute = TimeSpan.FromMilliseconds(800) };
    await using var c = Coordinator(session);
    var watch = Stopwatch.StartNew();
    var result = await c.ExecuteAsync(FakeSsh.Host(deadline: DateTimeOffset.UtcNow.AddMilliseconds(120)), FakeSsh.Execute(), default);
    Emit(new { test = "sync_execute", elapsed_ms = watch.ElapsedMilliseconds, status = result.Status.ToString(), c.ActiveStageWorkers });
}
{
    var session = new BlockingDispose();
    await using var c = Coordinator(session);
    var watch = Stopwatch.StartNew();
    var result = await c.TestAsync(FakeSsh.Host(deadline: DateTimeOffset.UtcNow.AddMilliseconds(120)), FakeSsh.Test(), default);
    Emit(new { test = "sync_dispose", elapsed_ms = watch.ElapsedMilliseconds, cleanup = result.CleanupState.ToString(), c.ActiveStageWorkers });
}
// The connect stage still owns the bytes until it returns.
{
    byte[] bytes = [17, 18, 19];
    var identity = new SshIdentityMaterial("/tmp/fake", "id_ed25519", bytes);
    var gate = new TaskCompletionSource<ISshTransportSession>(TaskCreationOptions.RunContinuationsAsynchronously);
    var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
    var factory = new FakeTransportFactory { OnConnect = (_, _) => { entered.SetResult(); return gate.Task; } };
    await using var c = new SshOperationCoordinator(factory, new FakeIdentityProvider { OnGet = _ => identity }, Opt());
    using var cancel = new CancellationTokenSource();
    var task = c.ExecuteAsync(FakeSsh.Host(), FakeSsh.Execute(), cancel.Token);
    await entered.Task.WaitAsync(TimeSpan.FromSeconds(2));
    cancel.Cancel();
    var result = await task.WaitAsync(TimeSpan.FromSeconds(2));
    Emit(new { test = "late_identity_ownership", bytes_zeroed_before_connect_completed = bytes.All(b => b == 0), connect_pending = !gate.Task.IsCompleted, c.ActiveStageWorkers, status = result.Status.ToString() });
    var late = new FakeSession();
    gate.SetResult(late);
    await FakeSsh.WaitUntilAsync(() => late.Disposed);
}
// An execution task that ignores cancellation, while Dispose itself completes.
{
    var gate = new TaskCompletionSource<SshExecuteResult>(TaskCreationOptions.RunContinuationsAsynchronously);
    var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
    var session = new FakeSession { OnExecute = (_, _, _, _) => { entered.SetResult(); return gate.Task; } };
    await using var c = Coordinator(session);
    using var cancel = new CancellationTokenSource();
    var op = c.ExecuteAsync(FakeSsh.Host(), FakeSsh.Execute(), cancel.Token);
    await entered.Task.WaitAsync(TimeSpan.FromSeconds(2));
    cancel.Cancel();
    var result = await op.WaitAsync(TimeSpan.FromSeconds(2));
    var stop = await c.StopAsync();
    Emit(new { test = "orphan_execute", execute_pending = !gate.Task.IsCompleted, c.ActiveLeases, c.ActiveStageWorkers, c.QuarantinedResources, stop, status = result.Status.ToString(), result.Diagnostic });
    gate.SetResult(FakeResults.Completed());
}
// Queue is accepted before first cleanup fills the quarantine; no re-check at admission.
{
    var gate = new TaskCompletionSource<SshExecuteResult>(TaskCreationOptions.RunContinuationsAsynchronously);
    var disposals = new List<TaskCompletionSource>();
    var factory = new FakeTransportFactory { OnConnect = (_, _) => { var d = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); disposals.Add(d); return Task.FromResult<ISshTransportSession>(new PendingDispose(gate.Task, d.Task)); } };
    await using var c = new SshOperationCoordinator(factory, new FakeIdentityProvider(), Opt(1) with { CoreMaxConcurrentOperations = 1 });
    var first = c.ExecuteAsync(FakeSsh.Host(), FakeSsh.Execute(), default);
    await FakeSsh.WaitUntilAsync(() => factory.ConnectCount == 1);
    var next = Enumerable.Range(0, 3).Select(_ => c.ExecuteAsync(FakeSsh.Host(), FakeSsh.Execute(), default)).ToArray();
    await FakeSsh.WaitUntilAsync(() => c.WaitQueueLength == 3);
    gate.SetResult(FakeResults.Completed());
    await Task.WhenAll(next.Append(first)).WaitAsync(TimeSpan.FromSeconds(4));
    Emit(new { test = "quarantine_overflow", c.QuarantineCapacity, c.QuarantinedResources, factory.ConnectCount });
    foreach (var d in disposals) d.SetResult();
    await FakeSsh.WaitUntilAsync(() => c.QuarantinedResources == 0);
}

class BlockingDispose : ISshTransportSession
{
    public string VerifiedHostKeySha256 => "fake";
    public string HostKeyAlgorithm => "ssh-ed25519";
    public bool IsConnected => true;
    public SshSubmissionEvidence SubmissionEvidence => SshSubmissionEvidence.NotSent;
    public void RequestAbort() { }
    public Task<SshExecuteResult> ExecuteAsync(string c, TimeSpan t, int b, CancellationToken ct) => Task.FromResult(FakeResults.Completed());
    public ValueTask DisposeAsync() { Thread.Sleep(800); return ValueTask.CompletedTask; }
}
class PendingDispose(Task<SshExecuteResult> execute, Task dispose) : ISshTransportSession
{
    public string VerifiedHostKeySha256 => "fake";
    public string HostKeyAlgorithm => "ssh-ed25519";
    public bool IsConnected => true;
    public SshSubmissionEvidence SubmissionEvidence => SshSubmissionEvidence.SubmissionAttempted;
    public void RequestAbort() { }
    public Task<SshExecuteResult> ExecuteAsync(string c, TimeSpan t, int b, CancellationToken ct) => execute;
    public ValueTask DisposeAsync() => new(dispose);
}
